H.background();
// Phase change & latent heat: heating curve of water.
// During a phase change, heat Q = m * L goes into breaking bonds, NOT raising T,
// so the temperature plateaus. Q = m*c*dT (sloped) vs Q = m*L (flat).
const m = P.m;          // mass in kg
const Lf = P.Lf * 1000; // latent heat of fusion, slider in kJ/kg -> J/kg
const Lv = P.Lv * 1000; // latent heat of vaporization, slider in kJ/kg -> J/kg
// Fixed specific heats for water phases (J/(kg*degC)).
const cIce = 2100, cWater = 4186, cSteam = 2010;
// Segment heat costs (J), in order: warm ice -20->0, melt, warm water 0->100, boil, warm steam 100->120.
const q1 = m * cIce * 20;
const q2 = m * Lf;
const q3 = m * cWater * 100;
const q4 = m * Lv;
const q5 = m * cSteam * 20;
const qTot = q1 + q2 + q3 + q4 + q5;
// Build the (Q, T) curve in kJ vs degC.
const k = 1 / 1000; // J -> kJ
const pts = [];
let Qacc = 0, Tacc = -20;
pts.push([Qacc * k, Tacc]);
Qacc += q1; Tacc = 0;   pts.push([Qacc * k, Tacc]);   // warm ice to 0
Qacc += q2;             pts.push([Qacc * k, Tacc]);   // melt (flat at 0)
Qacc += q3; Tacc = 100; pts.push([Qacc * k, Tacc]);   // warm water to 100
Qacc += q4;             pts.push([Qacc * k, Tacc]);   // boil (flat at 100)
Qacc += q5; Tacc = 120; pts.push([Qacc * k, Tacc]);   // warm steam to 120
const qTotk = qTot * k;
const v = H.plot2d({ xMin: 0, xMax: Math.max(1, qTotk) * 1.02, yMin: -30, yMax: 140 });
v.grid(); v.axes();
v.path(pts, { color: H.colors.accent, width: 3 });
// mark the two flat plateaus (latent heat) in a different color
v.path([pts[1], pts[2]], { color: H.colors.warn, width: 5 });
v.path([pts[3], pts[4]], { color: H.colors.warn, width: 5 });
// horizontal guide lines at melting (0) and boiling (100)
v.line(0, 0, qTotk, 0, { color: H.colors.violet, width: 1, dash: [4, 4] });
v.line(0, 100, qTotk, 100, { color: H.colors.violet, width: 1, dash: [4, 4] });
// Animate a dot riding the curve: sweep Q from 0 to qTot and loop.
const qNow = (t % 9) / 9 * qTot;   // joules added so far this loop
const qNowk = qNow * k;
// find the temperature at qNow by walking the segments
let T;
const seg = [[0, q1, -20, 0], [q1, q1 + q2, 0, 0], [q1 + q2, q1 + q2 + q3, 0, 100], [q1 + q2 + q3, q1 + q2 + q3 + q4, 100, 100], [q1 + q2 + q3 + q4, qTot, 100, 120]];
let phase = "solid (ice)";
for (let i = 0; i < seg.length; i++) {
  const [a, b, Ta, Tb] = seg[i];
  if (qNow <= b || i === seg.length - 1) {
    const f = b > a ? (qNow - a) / (b - a) : 0;
    T = Ta + (Tb - Ta) * H.clamp(f, 0, 1);
    if (i === 0) phase = "warming ice";
    else if (i === 1) phase = "MELTING (latent)";
    else if (i === 2) phase = "warming water";
    else if (i === 3) phase = "BOILING (latent)";
    else phase = "warming steam";
    break;
  }
}
v.dot(qNowk, T, { r: 7, fill: H.colors.yellow });
H.text("Phase change & latent heat:  Q = m·L", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("m = " + m.toFixed(2) + " kg    Lf = " + P.Lf.toFixed(0) + " kJ/kg    Lv = " + P.Lv.toFixed(0) + " kJ/kg", 24, 52, { color: H.colors.sub, size: 13 });
H.text("Q = " + qNowk.toFixed(1) + " kJ    T = " + T.toFixed(1) + " °C    " + phase, 24, 74, { color: H.colors.good, size: 13, weight: 600 });
H.legend([{ label: "T rises: Q = mcΔT", color: H.colors.accent }, { label: "plateau: Q = mL", color: H.colors.warn }], H.W - 210, 100);
